<script setup lang="ts">import type {Result} from '../types/entities';import PathRibbon from './PathRibbon.vue';defineProps<{result:Result}>();const groups:Record<string,string>={all:'全部观展路径',converted:'转化组',exited:'退出组'};function costText(result:Result){const c:any=result.edit_costs||result.study||{};return `补入 ${c.insert??c.insert_cost??1} · 删去 ${c.delete??c.delete_cost??1} · 替换 ${c.substitute??c.substitute_cost??1}`}function basisText(result:Result){return !result.cost_basis||result.cost_basis==='unit_cost_default'?'旧方案按单位成本解释':result.cost_basis==='mixed_study_unit_default'?'缺字段按单位成本补齐':'按方案成本'}</script><template><div class="medoid-panel"><p class="annotation">加权总距离按“实际路径→代表路径”方向累计，代表路径取总距离最小者；{{costText(result)}}（{{basisText(result)}}），平局按编码字典序。</p><section v-for="(title,key) in groups" :key="key"><p class="eyebrow">{{title}} / REPRESENTATIVE</p><template v-if="result.medoids[key]"><PathRibbon :path="result.medoids[key]!.path" :dictionary="result.dictionary"/><p class="annotation">{{result.medoids[key]!.journeys}}条路径 · 加权总距离{{result.medoids[key]!.weighted_total_distance}} · 平均距离{{result.medoids[key]!.mean_distance.toFixed(2)}}</p></template><p v-else class="annotation">该组没有观展路径，代表序列不可计算。</p></section></div></template>
